package com.bank.gateway;

import java.util.logging.*;

public class GatewayDemo {
    private static final Logger log = Logger.getLogger("GW");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ServiceRegistry registry = new ServiceRegistry();
        registry.register("/api/transfers", java.util.List.of("transfer-1", "transfer-2"));
        registry.register("/api/accounts", java.util.List.of("account-1"));

        ApiGateway gw = new ApiGateway(registry, new TokenAuth(), new SimpleRateLimiter(3));

        // Authenticated transfer request → routed + load-balanced + transformed
        log.info(() -> gw.handle("valid-rajesh", "/api/transfers", "{amount:50000}"));
        log.info(() -> gw.handle("valid-rajesh", "/api/transfers", "{amount:20000}"));

        // Unauthenticated request → 401
        log.info(() -> gw.handle("bad-token", "/api/accounts", "{}"));

        // Flood → after 3 allowed, throttle with 429
        for (int i = 0; i < 4; i++) {
            String resp = gw.handle("valid-bot", "/api/accounts", "{}");
            log.info(() -> "flood resp: " + resp);
        }
    }
}

