package com.bank.gateway;

import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ServiceRegistry {
    private final Map<String, List<String>> routes = new LinkedHashMap<>();
    private final Map<String, AtomicInteger> counters = new HashMap<>();

    public void register(String pathPrefix, List<String> instances) {
        routes.put(pathPrefix, instances);
        counters.put(pathPrefix, new AtomicInteger());
    }
    public String routeAndBalance(String path) {
        for (var e : routes.entrySet()) {
            if (path.startsWith(e.getKey())) {
                List<String> instances = e.getValue();
                int idx = counters.get(e.getKey()).getAndIncrement() % instances.size();
                return instances.get(idx);   // round-robin load balancing
            }
        }
        return null;
    }
}
