// ─── File: ApiGateway.java ───
package com.bank.gateway;

import java.util.logging.*;

public class ApiGateway {
    private static final Logger log = Logger.getLogger("GW");
    private final ServiceRegistry registry;
    private final TokenAuth auth;
    private final SimpleRateLimiter limiter;

    public ApiGateway(ServiceRegistry registry, TokenAuth auth, SimpleRateLimiter limiter) {
        this.registry = registry; this.auth = auth; this.limiter = limiter;
    }

    // single entry point: TLS terminated here, then the cross-cutting pipeline
    public String handle(String token, String path, String body) {
        // 1. authentication
        if (!auth.validate(token)) { log.warning(() -> "401 unauthorized " + path); return "401 Unauthorized"; }
        String user = auth.subject(token);

        // 2. rate limiting
        if (!limiter.allow(token)) { log.warning(() -> "429 throttled " + token); return "429 Too Many Requests"; }

        // 3. routing + load balancing
        String instance = registry.routeAndBalance(path);
        if (instance == null) { log.warning(() -> "404 no route " + path); return "404 Not Found"; }

        // 4. request transformation: inject verified identity header
        log.info(() -> "routed " + user + " " + path + " -> " + instance + " (X-User-Id=" + user + ")");

        // 5. response transformation: wrap/clean internal response
        String internal = instance + " handled " + body;
        return transformResponse(internal, user);
    }

    private String transformResponse(String internal, String user) {
        // strip internal details, add a clean envelope for the client
        return "{\"status\":\"OK\",\"user\":\"" + user + "\",\"result\":\"done\"}";
    }
}
